                "sampleValue": "calendar-sample-001"
              },
              "title": {
                "type": "string",
                "description": "日程标题，优先展示今天的出行安排。",
                "sampleValue": "陪诊打车去医院"
              },
              "eventLocation": {
                "type": "string",
                "description": "日程发生地点或目的地。",
                "sampleValue": "市一医院门诊楼"
              },
              "dtStart": {
                "type": "string",
                "description": "日程当天开始时间，通常为 HH:MM 格式。",
                "sampleValue": "09:00"
              },
              "dtEnd": {
                "type": "string",
                "description": "日程当天结束时间，通常为 HH:MM 格式。",
                "sampleValue": "10:30"
              }
            }
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_car.png",
      "description": "汽车/打车图标，适合雨天打车卡片中作为出行服务识别和视觉锚点。"
    }
  ]
}

